{
  "title": "Multiple Failed Kerberos TGT Requests (Credential Stuffing)",
  "id": "e3b1c9f2-5d4a-4c6f-9a2e-1f2d3c4b5a6d",
  "description": "Detects 5 or more failed Kerberos TGT (EventID 4768) attempts from the same source IP within a 5 minute window, indicating possible credential stuffing.",
  "status": "experimental",
  "logsource": {
    "product": "windows",
    "service": "security"
  },
  "detection": {
    "selection": {
      "EventID": 4768,
      "LogonType": 2,
      "Outcome": "failure"
    },
    "groupby": ["SourceIP"],
    "condition": "selection | count() by SourceIP >= 5 within 5m"
  },
  "fields": ["SourceIP", "TargetUserName", "TargetDomainName", "Timestamp"],
  "falsepositives": ["Legitimate high volume authentication testing"],
  "level": "high"
}

{
  "title": "Permissive inbound ACL allowing port 4444",
  "id": "RULE-2026-ACL-4444",
  "description": "Detects creation or modification of firewall ACL rules that allow inbound traffic from any source to destination port 4444, which may indicate malicious configuration change.",
  "author": "SOC Team",
  "date": "2026-10-03",
  "logsource": {
    "product": "firewall",
    "service": "configuration"
  },
  "detection": {
    "selection": {
      "event_type": "acl_change",
      "direction": "inbound",
      "dest_port": 4444,
      "src": "any"
    },
    "condition": "selection"
  },
  "level": "high",
  "status": "experimental",
  "tags": ["network", "firewall", "acl", "port_4444"]
}
